import type { Metadata } from 'next'
import { notFound } from 'next/navigation'
import type { Comment, Post } from '@/lib/types'
import { BackButton } from './back-button'

export const dynamicParams = true

async function getPost(id: string): Promise<Post> {
  const res = await fetch(`https://jsonplaceholder.typicode.com/posts/${id}`, {
    next: { revalidate: 300 },
  })
  if (!res.ok) {
    notFound()
  }
  return res.json()
}

async function getComments(id: string): Promise<Comment[]> {
  const res = await fetch(
    `https://jsonplaceholder.typicode.com/posts/${id}/comments`,
    { next: { revalidate: 300 } }
  )
  if (!res.ok) {
    notFound()
  }
  return res.json()
}

export async function generateStaticParams(): Promise<{ id: string }[]> {
  const posts: Post[] = await fetch(
    'https://jsonplaceholder.typicode.com/posts'
  ).then((res) => res.json())

  return posts.slice(0, 10).map((post) => ({
    id: post.id.toString(),
  }))
}

export async function generateMetadata({
  params,
}: PageProps<'/blog/[id]'>): Promise<Metadata> {
  const { id } = await params

  try {
    const post = await getPost(id)

    return {
      title: `${post.title} - My Blog`,
      description: post.body.substring(0, 160),
      openGraph: {
        title: post.title,
        description: post.body.substring(0, 160),
      },
    }
  } catch {
    return {
      title: 'Post Not Found - My Blog',
    }
  }
}

export default async function BlogPost({ params }: PageProps<'/blog/[id]'>) {
  const { id } = await params

  let post: Post
  let comments: Comment[]

  try {
    ;[post, comments] = await Promise.all([getPost(id), getComments(id)])
  } catch {
    notFound()
  }

  return (
    <article>
      <BackButton />

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  )
}

